query:
create table if not exists public.attendance_records (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  academic_year_id uuid references public.academic_years(id) on delete set null,
  class_id uuid references public.classes(id) on delete set null,
  attendance_date date not null default current_date,
  status text not null check (status in ('present','absent','late','excused')),
  note text,
  recorded_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (student_id, attendance_date)
);

create table if not exists public.subjects (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  name text not null,
  code text,
  created_at timestamptz not null default now(),
  unique (school_id, name)
);

create table if not exists public.assessments (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  academic_year_id uuid references public.academic_years(id) on delete set null,
  class_id uuid references public.classes(id) on delete set null,
  subject_id uuid references public.subjects(id) on delete set null,
  title text not null,
  assessment_date date not null default current_date,
  maximum_score numeric(6,2) not null default 20 check (maximum_score > 0),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create table if not exists public.grades (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  assessment_id uuid not null references public.assessments(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  score numeric(6,2) not null check (score >= 0),
  comment text,
  created_at timestamptz not null default now(),
  unique (assessment_id, student_id)
);

create table if not exists public.payments (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  student_id uuid references public.students(id) on delete set null,
  amount numeric(14,2) not null check (amount > 0),
  currency text not null default 'XOF',
  payment_date date not null default current_date,
  method text,
  reference text,
  note text,
  recorded_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create table if not exists public.school_documents (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  media_asset_id uuid references public.media_assets(id) on delete set null,
  title text not null,
  category text,
  issued_on date,
  expires_on date,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create table if not exists public.calendar_events (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  title text not null,
  description text,
  category text,
  starts_at timestamptz not null,
  ends_at timestamptz,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check (ends_at is null or ends_at >= starts_at)
);

create index if not exists attendance_school_date_idx on public.attendance_records (school_id, attendance_date);
create index if not exists assessments_school_date_idx on public.assessments (school_id, assessment_date);
create index if not exists payments_school_date_idx on public.payments (school_id, payment_date);
create index if not exists documents_school_idx on public.school_documents (school_id);
create index if not exists calendar_events_school_start_idx on public.calendar_events (school_id, starts_at);

alter table public.attendance_records enable row level security;
alter table public.subjects enable row level security;
alter table public.assessments enable row level security;
alter table public.grades enable row level security;
alter table public.payments enable row level security;
alter table public.school_documents enable row level security;
alter table public.calendar_events enable row level security;

create policy attendance_member_access on public.attendance_records for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy subjects_member_access on public.subjects for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy assessments_member_access on public.assessments for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy grades_member_access on public.grades for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy payments_member_access on public.payments for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy documents_member_access on public.school_documents for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
create policy calendar_member_access on public.calendar_events for all to authenticated using (public.is_school_member(school_id)) with check (public.is_school_member(school_id));
